    q("qx_038","Lineas de DOCLIN con codigo duplicado en el mismo documento","Hay lineas de detalle con el mismo articulo repetido en el mismo documento?","DOCLIN con mismo CODDOCUMENTO y CODIGO mas de una vez.","SELECT CODDOCUMENTO, CODIGO, COUNT(*) AS N FROM DOCLIN WHERE CODIGO IS NOT NULL AND CODIGO!='' GROUP BY CODDOCUMENTO, CODIGO HAVING COUNT(*)>1 ORDER BY N DESC LIMIT 20","Todos","Calidad","Calidad","Medio","",""),
