    q("qx_044","Documentos con IMPORTEIVA negativo","Hay documentos con IMPORTEIVA negativo?","DOCCAB donde IMPORTEIVA < 0.","SELECT TIPO, COUNT(*) AS N_DOCS FROM DOCCAB WHERE COALESCE(IMPORTEIVA,0) < 0 GROUP BY TIPO ORDER BY N_DOCS DESC","Todos","Calidad","Calidad","Alto","",""),
