    q("qx_048","Documentos con DESCUENTOS NULL","Hay documentos con descuento nulo?","DOCCAB donde DESCUENTOS IS NULL.","SELECT TIPO, COUNT(*) AS N_DOCS FROM DOCCAB WHERE DESCUENTOS IS NULL GROUP BY TIPO ORDER BY N_DOCS DESC","Todos","Calidad","Calidad","Bajo","",""),
    q("qx_049","Documentos con CODFORMAPAGO NULL","Hay documentos sin forma de pago asignada?","DOCCAB donde CODFORMAPAGO IS NULL o CODFORMAPAGO=''.","SELECT TIPO, COUNT(*) AS N_DOCS FROM DOCCAB WHERE CODFORMAPAGO IS NULL OR CODFORMAPAGO='' GROUP BY TIPO ORDER BY N_DOCS DESC","Todos","Calidad","Calidad","Medio","",""),
